INSERT INTO `landing_kepala_sekolah` (`id`, `nama`, `foto`, `moto1`, `moto2`, `moto3`, `moto4`) VALUES
(1, '<h2>KEPALA SEKOLAH</h2>\r\n<p>HASNI IRJAYANTI, S. Pd</p>', 'HASNI.png', '<h4>Unggul Akademik</h4>\r\n<p>Menggabungkan metodologi pengajaran terbaik dengan alat-alat digital mutakhir.</p>', '<h4>Raih Potensi</h4>\r\n<p>Membuka dan memaksimalkan setiap potensi unik siswa melalui kurikulum digital yang dipersonalisasi.</p>', '<h4>Integritas Digital</h4>\r\n<p>Kami membentuk karakter siswa dengan fondasi integritas dan etika digital yang kuat.</p>', '<h4>Belajar Transformasi</h4>\r\n<p>Memimpin perubahan paradigma pendidikan melalui adopsi teknologi digital yang terintegrasi penuh.</p>');
